import sqlite3
import sys
import re
import csv
from datetime import datetime, timezone
import operator

def parse_where_condition(where_str):
    conditions = where_str.split(' AND ')
    parsed = []
    for cond in conditions:
        parts = cond.split()
        if len(parts) != 3:
            raise ValueError(f"Invalid condition format: {cond}")
        col, op, lit = parts
        if op not in ('=', '>', '<'):
            raise ValueError(f"Invalid operator: {op}")
        try:
            if lit.startswith("'") and lit.endswith("'"):
                parsed.append((col, op, lit[1:-1]))
            else:
                parsed.append((col, op, float(lit)))
        except ValueError:
            raise ValueError(f"Invalid literal: {lit}")
    return parsed

def evaluate_formula(row, formula):
    try:
        # Replace column names with their values
        for col in ['id', 'region', 'amount', 'tax_rate']:
            row[col] = str(row[col])
        # Replace column names with variables in the formula
        formula = re.sub(r'\b(id|region|amount|tax_rate)\b', lambda m: str(row[m.group()]), formula)
        # Evaluate the arithmetic expression
        return eval(formula, {'__builtins__': None}, {})
    except Exception as e:
        raise ValueError(f"Formula evaluation error: {str(e)}")

def main():
    if len(sys.argv) < 4:
        print("Usage: python filter_sales.py <db_path> --where <condition> --formula <expression>", file=sys.stderr)
        sys.exit(1)

    db_path = sys.argv[1]
    where_str = sys.argv[2]
    formula = sys.argv[3]

    try:
        conn = sqlite3.connect(db_path)
        cursor = conn.cursor()
        cursor.execute("SELECT id, region, amount, tax_rate FROM sales")
        rows = cursor.fetchall()
        conn.close()
    except Exception as e:
        print(f"Database error: {str(e)}", file=sys.stderr)
        sys.exit(1)

    try:
        where_conditions = parse_where_condition(where_str)
        filtered_rows = []
        for row in rows:
            row_dict = dict(zip(['id', 'region', 'amount', 'tax_rate'], row))
            for col, op, lit in where_conditions:
                if col == 'region':
                    if op == '=' and row_dict[col] != lit:
                        break
                    if op == '>' and row_dict[col] <= lit:
                        break
                    if op == '<' and row_dict[col] >= lit:
                        break
                else:
                    if op == '=' and row_dict[col] != lit:
                        break
                    if op == '>' and row_dict[col] <= lit:
                        break
                    if op == '<' and row_dict[col] >= lit:
                        break
            else:
                computed = evaluate_formula(row_dict, formula)
                formatted_computed = "{0:.2f}".format(computed)
                filtered_rows.append((row_dict['id'], row_dict['region'], row_dict['amount'], row_dict['tax_rate'], formatted_computed))

        if not filtered_rows:
            print("No rows matched the criteria.", file=sys.stderr)
            sys.exit(1)

        with open('query.log', 'a') as log_file:
            timestamp = datetime.now(timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")
            log_file.write(f"{timestamp} | OK | {len(filtered_rows)}\n")

        with open('result.csv', 'w', newline='') as csvfile:
            writer = csv.writer(csvfile)
            writer.writerow(['id', 'region', 'amount', 'tax_rate', 'computed'])
            writer.writerows(filtered_rows)

    except Exception as e:
        timestamp = datetime.now(timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")
        with open('query.log', 'a') as log_file:
            log_file.write(f"{timestamp} | ERROR | {str(e)}\n")
        print(f"Error: {str(e)}", file=sys.stderr)
        sys.exit(1)

if __name__ == "__main__":
    main()
